  // Платная линия: скин на 1-м уровне и самый редкий на последнем, как в игре; остальное ровно по уровням.
  const outf=paid.filter(x=>x.t==='o').sort((a,b)=>rk(a)-rk(b)), rest=paid.filter(x=>x.t!=='o').sort((a,b)=>rk(a)-rk(b));
